grep -rn "struct FixedClock\|struct SequentialIdGenerator\|trait HttpTransport" core/src/ | head -20; echo '--- time_util ---'; grep -n 'pub use' core/src/openmtr/time_util.rs core/src/openmtr/transport/mod.rs core/src/lib.rs 2>/dev/null | head -30
```

